"""Plain-text absence notices for parents."""

from rosterkit.models import Student
from rosterkit.errors import ProjectError

ABSENT = "absent"

def absent_days(student: Student, marks: list) -> list:
    """Sorted absent dates; marks must be the student's."""
    for mark in marks:
        if mark.student_id != student.student_id:
            raise ProjectError("mark for another student")
    gone = [mark for mark in marks if mark.status == ABSENT]
    return sorted(mark.day for mark in gone)

def build_notice(student: Student, marks: list) -> str:
    """Short notice: student, count and dates missed."""
    days = absent_days(student, marks)
    if not days:
        raise ProjectError("no absences to report")
    dates = ", ".join(stamp.isoformat() for stamp in days)
    name = f"{student.first_name} {student.last_name}"
    return f"{name} missed {len(days)} day(s): {dates}."
